"""Build the download ZIP and the Worker's embedded copy of the same runner."""
import argparse
import json
from pathlib import Path
import zipfile

root = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser()
parser.add_argument('--backend', type=Path, required=True, help='Backend repository root')
args = parser.parse_args()
source = root / 'promptflow-cli'
runtime = (source / 'src/promptflow_cli/runtime.py').read_text('utf-8')
(args.backend / 'src/promptflow_local_runtime.ts').write_text(
    '// Generated by scripts/build-promptflow-cli.py. Edit promptflow-cli/src/promptflow_cli/runtime.py.\n'
    + 'export const LOCAL_RUNTIME_PY = ' + json.dumps(runtime, ensure_ascii=True) + ';\n', encoding='utf-8')
with zipfile.ZipFile(root / 'promptflow-cli.zip', 'w', zipfile.ZIP_DEFLATED) as archive:
    for file in sorted(source.rglob('*')):
        if not file.is_file() or any(p in ('__pycache__','.venv','.pytest_cache','tests') or p.endswith('.egg-info') for p in file.relative_to(source).parts):
            continue
        if file.suffix in ('.pyc','.pyo'): continue
        archive.write(file, 'promptflow-cli/' + file.relative_to(source).as_posix())
print('Built promptflow-cli.zip and backend/src/promptflow_local_runtime.ts')
